// ui-general · кейсы ui-09, ui-10 (.qa/tests/ui-general/) — מובייל: RTL, פריסה, שדות קומפקטיים (только чтение)
import { test, expect, Page, Locator } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

const noHorizontalScroll = async (page: Page) =>
  expect(await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)).toBeLessThanOrEqual(1);
const box = async (l: Locator) => (await l.boundingBox())!;
const fitsText = async (l: Locator) => expect(await l.evaluate((e) => e.scrollWidth - e.clientWidth)).toBeLessThanOrEqual(1);

test.describe('ui-general — מובייל (מפיץ)', () => {
  test.use({ storageState: auth('admin') });

  test('לוח בקרה: שדות התאריכים בדוח רו״ח קומפקטיים והתאריך מלא #6a8597e8 @mobile @prod-safe', async ({ page }) => {
    await page.goto('/dashboard');
    const fromF = page.getByRole('textbox', { name: 'מתאריך' });
    const toF = page.getByRole('textbox', { name: 'עד תאריך' });
    await fromF.scrollIntoViewIfNeeded({ timeout: 20_000 });
    const vw = page.viewportSize()!.width;
    for (const f of [fromF, toF]) {
      expect((await box(f)).width).toBeLessThan(vw * 0.6);
      await fitsText(f);
    }
    expect((await box(fromF)).x).toBeGreaterThan((await box(toF)).x); // RTL: «מתאריך» справа
    await noHorizontalScroll(page);
  });

  test('מוצרים: כפתורים עליונים מימין מתחת לכותרת, «עודכן לאחרונה» מלא, לשוניות מימין #6a8597e8 @mobile @prod-safe', async ({ page }) => {
    await page.goto('/catalog');
    const h1 = page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' });
    await expect(h1).toBeVisible({ timeout: 20_000 });
    const all = page.getByRole('button', { name: /^הכל\s*\d+$/ });
    await expect(all).toBeVisible({ timeout: 20_000 });
    const h = await box(h1);
    const right = h.x + h.width;
    for (const name of ['קטגוריות', 'מוצר חדש']) {
      const b = await box(page.getByRole('button', { name, exact: true }));
      expect(b.y).toBeGreaterThan(h.y + h.height - 1);
      expect(Math.abs(b.x + b.width - right)).toBeLessThanOrEqual(2);
    }
    const a = await box(all);
    expect(Math.abs(a.x + a.width - right)).toBeLessThanOrEqual(2);
    expect(a.x).toBeGreaterThan((await box(page.getByRole('button', { name: /^זמינים\s*\d+$/ }))).x);
    expect((await box(page.getByRole('button', { name: /^זמינים\s*\d+$/ }))).x).toBeGreaterThan((await box(page.getByRole('button', { name: /^לא זמינים\s*\d+$/ }))).x);
    await expect(page.getByText(/^\d{2}\.\d{2}\.\d{4}$/).first()).toBeVisible();
    await fitsText(page.getByText('עודכן לאחרונה').locator('..'));
    await noHorizontalScroll(page);
  });

  // #4f5292 (26.10): на телефоне строки — карточки (статусы под номером, «⋮» в первой строке) → перекрытие считается по площади,
  // а не только по горизонтали; «⋮» должен быть в пределах экрана без прокрутки вбок. Подробно — tests/orders/orders-mobile-cards.spec.ts.
  test('הזמנות: לשוניות מימין; הסטטוס לא חופף לכפתור ⋮ #6a8597e8 #4f5292 @mobile @prod-safe', async ({ page }) => {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    const all = page.getByRole('button', { name: /^הכל \d+$/ });
    await expect(all).toBeVisible({ timeout: 20_000 });
    const h = await box(page.getByRole('heading', { level: 1, name: 'הזמנות' }));
    const a = await box(all);
    expect(Math.abs(a.x + a.width - (h.x + h.width))).toBeLessThanOrEqual(2);
    expect(a.x).toBeGreaterThan((await box(page.getByRole('button', { name: /^ממתינות לאישור \d+$/ }))).x);
    await noHorizontalScroll(page);
    const rows = page.getByRole('button', { name: /^#\d+ / });
    await expect(rows.first()).toBeVisible({ timeout: 20_000 });
    const res = await rows.evaluateAll((els) =>
      els.slice(0, 8).map((r) => {
        const btns = r.querySelectorAll('button');
        const b = btns[btns.length - 1];
        if (!b) return { overlap: 0, inView: true };
        const br = b.getBoundingClientRect();
        const pills = [...r.querySelectorAll('span,div')].filter((k) => k.children.length <= 1 && /אושרה|ממתינה|נדחתה|סופק|בדרך|מוכנ|בליקוט|בהכנה/.test(k.textContent || '') && (k.textContent || '').length < 40);
        const overlap = Math.max(0, ...pills.map((p) => {
          const pr = p.getBoundingClientRect();
          const w = Math.min(pr.right, br.right) - Math.max(pr.left, br.left);
          const h = Math.min(pr.bottom, br.bottom) - Math.max(pr.top, br.top);
          return w > 0 && h > 0 ? w * h : 0;
        }));
        return { overlap, inView: br.left >= 0 && br.right <= window.innerWidth + 1 };
      }),
    );
    expect(res.every((o) => o.overlap === 0)).toBe(true);
    expect(res.every((o) => o.inView)).toBe(true);
  });

  test('תעודת משלוח: «תאריך אספקה» קומפקטי והתאריך מוצג במלואו #6a8597e8 @mobile @prod-safe', async ({ page }) => {
    await page.goto('/delivery');
    const note = page.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ }).first();
    await expect(note).toBeVisible({ timeout: 20_000 });
    // центр карточки перекрыт ссылкой адреса (Google Maps, by design) — переходим по href карточки
    await page.goto((await note.getAttribute('href'))!);
    const date = page.getByLabel('תאריך אספקה');
    await expect(date).toBeVisible({ timeout: 20_000 });
    await date.scrollIntoViewIfNeeded();
    expect((await box(date)).width).toBeLessThan(page.viewportSize()!.width * 0.6);
    await fitsText(date);
    await noHorizontalScroll(page);
  });
});

test.describe('ui-general — מובייל (לקוח) RTL', () => {
  test.use({ storageState: auth('buyer') });

  test('עברית RTL בכל מסכי הלקוח, בלי גלילה אופקית, מצב ריק/רשימות בעברית #6a38cf5a @mobile @prod-safe', async ({ page }) => {
    for (const u of ['/shop', '/shop/cart', '/shop/orders']) {
      await page.goto(u);
      await page.waitForLoadState('networkidle').catch(() => {});
      await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');
      await expect(page.locator('html')).toHaveAttribute('lang', 'he');
      await noHorizontalScroll(page);
    }
    await expect(page.getByRole('heading', { name: 'ההזמנות שלי' })).toBeVisible();
    for (const t of ['קטלוג', 'עגלה', 'הזמנות']) await expect(page.getByText(t, { exact: true }).last()).toBeVisible();
  });

  test('חיפוש בעברית: יישור לימין וסינון תוצאות #6a38cf5a @mobile @prod-safe', async ({ page }) => {
    await page.goto('/shop');
    const search = page.getByPlaceholder('חיפוש מוצר…');
    await expect(search).toBeVisible({ timeout: 20_000 });
    expect(await search.evaluate((e) => getComputedStyle(e).direction)).toBe('rtl');
    await search.fill('מצית קליפט');
    await expect(search).toHaveValue('מצית קליפט');
    await expect(page.getByText('מצית קליפט', { exact: true }).first()).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('רד לייבל 200 מ"ל')).toHaveCount(0);
  });
});
